let cached;

export async function loadFsevents() {
  if (cached !== undefined) return cached;

  if (process.platform !== "darwin") {
    cached = null;
    return cached;
  }

  try {
    cached = (await import("fsevents")).default;
  } catch {
    cached = null;
  }

  return cached;
}

import { EventEmitter } from "node:events";
import { loadFsevents } from "./load-fsevents.js";

export class FSEventsWatcher extends EventEmitter {
  constructor(paths, options = {}) {
    super();
    this.paths = Array.isArray(paths) ? paths : [paths];
    this.options = options;
    this.stops = [];
    this.closed = false;
    this.fsevents = null;
  }

  async start() {
    const fsevents = await loadFsevents();
    if (!fsevents) {
      throw new Error("native fsevents module is not available");
    }

    this.fsevents = fsevents;

    for (const target of this.paths) {
      const stop = fsevents.watch(
        target,
        (path, flags, id) => this.#onEvent(path, flags, id),
        {
          latency: this.options.latency ?? 0.25,
          since: this.options.since ?? undefined,
          flags: this.options.flags,
        },
      );
      this.stops.push(stop);
    }

    this.emit("ready");
    return this;
  }

  #onEvent(path, flags, id) {
    const info = this.fsevents.getInfo(path, flags);
    const event = {
      path,
      id,
      event: info.event,
      type: info.type,
      changes: info.changes,
      flags,
    };

    this.emit("event", event);
    this.emit(info.event, event);
  }

  close() {
    if (this.closed) return;
    this.closed = true;

    for (const stop of this.stops) {
      try {
        stop();
      } catch {}
    }

    this.stops = [];
    this.emit("close");
  }
}

import { EventEmitter } from "node:events";
import fs from "node:fs";
import path from "node:path";

export class FallbackWatcher extends EventEmitter {
  constructor(paths, options = {}) {
    super();
    this.paths = Array.isArray(paths) ? paths : [paths];
    this.options = options;
    this.watchers = [];
    this.closed = false;
  }

  async start() {
    for (const target of this.paths) {
      let stat;
      try {
        stat = fs.statSync(target);
      } catch (err) {
        this.emit("error", err);
        continue;
      }

      const recursive = stat.isDirectory() && this.options.recursive !== false;
      let watcher;
      try {
        watcher = fs.watch(target, { recursive, persistent: true }, (eventType, filename) => {
          const full = filename ? path.join(target, filename.toString()) : target;
          const event = eventType === "rename" ? "renamed" : "modified";
          const info = { path: full, id: -1, event, type: "unknown", changes: {}, flags: 0 };
          this.emit("event", info);
          this.emit(event, info);
        });
      } catch (err) {
        this.emit("error", err);
        continue;
      }

      watcher.on("error", (err) => this.emit("error", err));
      this.watchers.push(watcher);
    }

    this.emit("ready");
    return this;
  }

  close() {
    if (this.closed) return;
    this.closed = true;

    for (const watcher of this.watchers) {
      try {
        watcher.close();
      } catch {}
    }

    this.watchers = [];
    this.emit("close");
  }
}

import { FSEventsWatcher } from "./fsevents-watcher.js";
import { FallbackWatcher } from "./fallback-watcher.js";
import { loadFsevents } from "./load-fsevents.js";

export async function watch(paths, options = {}) {
  const native = await loadFsevents();

  if (native) {
    return new FSEventsWatcher(paths, options).start();
  }

  if (options.native === true) {
    throw new Error("native fsevents backend is unavailable on this platform");
  }

  return new FallbackWatcher(paths, options).start();
}

export { FSEventsWatcher, FallbackWatcher, loadFsevents };

#!/usr/bin/env node
import process from "node:process";
import { watch } from "../src/index.js";

function parseArgs(argv) {
  const options = { json: false, native: false, latency: 0.25, targets: [] };

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];

    if (arg === "-h" || arg === "--help") {
      options.help = true;
    } else if (arg === "--json") {
      options.json = true;
    } else if (arg === "--native") {
      options.native = true;
    } else if (arg === "--latency") {
      options.latency = Number(argv[(i += 1)]);
    } else if (arg.startsWith("--latency=")) {
      options.latency = Number(arg.slice("--latency=".length));
    } else if (arg.startsWith("-")) {
      options.unknown = arg;
    } else {
      options.targets.push(arg);
    }
  }

  return options;
}

function usage() {
  return [
    "Usage: fswatch-native [options] <path...>",
    "",
    "Options:",
    "  --json           emit newline-delimited JSON events",
    "  --native         require the native fsevents backend",
    "  --latency <sec>  FSEvents coalescing latency (default 0.25)",
    "  -h, --help       show this help",
  ].join("\n");
}

const options = parseArgs(process.argv.slice(2));

if (options.help) {
  console.log(usage());
  process.exit(0);
}

if (options.unknown) {
  console.error(`unknown option: ${options.unknown}\n`);
  console.error(usage());
  process.exit(2);
}

if (options.targets.length === 0) {
  console.error("at least one path is required\n");
  console.error(usage());
  process.exit(2);
}

const watcher = await watch(options.targets, options);

watcher.on("error", (err) => {
  console.error(`watch error: ${err.message}`);
});

watcher.on("event", (event) => {
  if (options.json) {
    console.log(JSON.stringify(event));
    return;
  }

  const stamp = new Date().toISOString();
  console.log(`${stamp} ${event.event.padEnd(12)} ${event.type.padEnd(7)} ${event.path}`);
});

process.on("SIGINT", () => {
  watcher.close();
  process.exit(0);
});

process.on("SIGTERM", () => {
  watcher.close();
  process.exit(0);
});

