import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { watch } from "./src/index.js";

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "fswatch-"));
const w = await watch([dir]);
console.log("watcher:", w.constructor.name);

const seen = new Promise((resolve) => {
  w.once("event", (e) => resolve(e));
});

setTimeout(() => fs.writeFileSync(path.join(dir, "hello.txt"), "hi"), 150);
const event = await Promise.race([seen, new Promise((_, r) => setTimeout(() => r(new Error("no event")), 3000))]);
console.log("event:", event.event, event.path.endsWith("hello.txt"));
w.close();
fs.rmSync(dir, { recursive: true, force: true });
' 2>&1

